insert into public.place_translations (place_id, lang, name, short_desc, best_time)
select p.id, v.lang, v.name, v.short_desc, v.best_time
from (values
  ('isa-bey-camii', 'tr', 'İsa Bey Camii', 'Selçuk''ta, Aydınoğulları döneminde 1375''te yapılan; avlusu ve antik sütunlarıyla Beylikler mimarisinin önemli örneği.', null),
  ('isa-bey-camii', 'en', 'İsa Bey Mosque', 'Built in Selçuk in 1375 under the Aydınids; with its courtyard and reused ancient columns, a key work of Beylik-era architecture.', null),
  ('hisar-camii', 'tr', 'Hisar Camii', 'Kemeraltı''nda, 16. yüzyılın sonunda yapılan, İzmir''in en büyük tarihi camisi; içi kalem işleriyle süslü.', null),
  ('hisar-camii', 'en', 'Hisar Mosque', 'Izmir''s largest historic mosque, built in Kemeraltı at the end of the 16th century and decorated with painted ornament inside.', null),
  ('konak-camii', 'tr', 'Konak (Yalı) Camii', 'Konak Meydanı''nda, Saat Kulesi''nin yanında duran, çinilerle kaplı küçük sekizgen cami; Yalı Camii olarak da bilinir.', null),
  ('konak-camii', 'en', 'Konak Mosque', 'A small octagonal mosque clad in tiles beside the Clock Tower on Konak Square, also known as the Yalı Mosque.', null),
  ('basdurak-camii', 'tr', 'Başdurak Camii', 'Kemeraltı''nda 17. yüzyılda yapılan, çarşının içinde kalan tarihi cami.', null),
  ('basdurak-camii', 'en', 'Başdurak Mosque', 'A 17th-century mosque tucked inside the Kemeraltı bazaar.', null),
  ('aydinoglu-mehmet-bey-camii', 'tr', 'Aydınoğlu Mehmet Bey Camii', 'Birgi''de, Aydınoğlu Mehmet Bey''in 1312''de yaptırdığı Ulu Cami; ahşap minberi ve çinileriyle ünlü.', null),
  ('aydinoglu-mehmet-bey-camii', 'en', 'Birgi Grand Mosque', 'Birgi''s Great Mosque, built by Aydınoğlu Mehmet Bey in 1312 and known for its carved wooden pulpit and tiles.', null),
  ('salepcioglu-camii', 'tr', 'Salepçioğlu Camii', 'Kemeraltı''nda 20. yüzyılın başında yapılan, iç süslemeleri ve kubbesiyle dikkat çeken cami.', null),
  ('salepcioglu-camii', 'en', 'Salepçioğlu Mosque', 'An early 20th-century mosque in Kemeraltı, notable for its dome and richly decorated interior.', null),
  ('kestanepazari-camii', 'tr', 'Kestanepazarı Camii', 'Kemeraltı''nın Kestanepazarı bölgesinde 17. yüzyılda yapılan cami; avlusu çarşının ortasında bir mola yeri.', null),
  ('kestanepazari-camii', 'en', 'Kestanepazarı Mosque', 'A 17th-century mosque in the Kestanepazarı quarter of Kemeraltı, its courtyard a quiet stop in the bazaar.', null),
  ('bergama-kursunlu-cami', 'tr', 'Bergama Kurşunlu Cami', 'Bergama''da 15. yüzyılın ortasında yapılan, kubbesi kurşunla kaplı erken Osmanlı camisi.', null),
  ('bergama-kursunlu-cami', 'en', 'Bergama Kurşunlu Mosque', 'An early Ottoman mosque in Bergama from the mid-15th century, named for its lead-covered dome.', null),
  ('bergama-ulu-cami', 'tr', 'Bergama Ulu Cami', 'Bergama''da Yıldırım Bayezid döneminde yapılan, kentin en eski camilerinden Ulu Cami.', null),
  ('bergama-ulu-cami', 'en', 'Bergama Grand Mosque', 'Bergama''s Great Mosque, built under Bayezid I and one of the town''s oldest mosques.', null),
  ('tire-ulu-camii', 'tr', 'Tire Ulu Camii', 'Tire''de Aydınoğulları döneminden kalan, ilçenin en eski ve en büyük camilerinden.', null),
  ('tire-ulu-camii', 'en', 'Tire Grand Mosque', 'One of the oldest and largest mosques of Tire, dating from the Aydınid period.', null),
  ('sadirvanalti-camii', 'tr', 'Şadırvanaltı Camii', 'Kemeraltı''nda 17. yüzyılda yapılan; alt katı dükkânlar, avlusunda şadırvanı olan cami.', null),
  ('sadirvanalti-camii', 'en', 'Şadırvanaltı Mosque', 'A 17th-century Kemeraltı mosque raised above shops, with a fountain in its courtyard.', null),
  ('meryem-ana-evi', 'tr', 'Meryem Ana Evi', 'Bülbül Dağı''nda, Hz. Meryem''in son yıllarını geçirdiğine inanılan ev; Hristiyanlar ve Müslümanlar için kutsal.', null),
  ('meryem-ana-evi', 'en', 'House of the Virgin Mary', 'The house on Mount Koressos where the Virgin Mary is believed to have spent her last years; sacred to Christians and Muslims.', null),
  ('aziz-yuhanna-katedrali', 'tr', 'Aziz Yuhanna Katedrali', 'Alsancak''ta 19. yüzyılın ortasında yapılan, İzmir''in Katolik katedrali.', null),
  ('aziz-yuhanna-katedrali', 'en', 'St. John''s Cathedral', 'Izmir''s Catholic cathedral in Alsancak, built in the mid-19th century.', null),
  ('aziz-polikarp-kilisesi', 'tr', 'Aziz Polikarp Kilisesi', 'İzmir''in bugün de açık olan en eski kilisesi; adını şehrin ilk piskoposu Polikarp''tan alır.', null),
  ('aziz-polikarp-kilisesi', 'en', 'Saint Polycarp Church', 'The oldest church still in use in Izmir, named after Polycarp, the city''s first bishop.', null),
  ('santa-maria-katolik-kilisesi', 'tr', 'Santa Maria Katolik Kilisesi', 'Bornova''da, Levanten ailelerin 19. yüzyılda yaptırdığı Katolik kilisesi.', null),
  ('santa-maria-katolik-kilisesi', 'en', 'Saint Mary''s Catholic Church', 'A 19th-century Catholic church in Bornova, built by the town''s Levantine families.', null),
  ('ayios-haralambos-kilisesi', 'tr', 'Ayios Haralambos Kilisesi', 'Çeşme''de 19. yüzyılda yapılan Rum Ortodoks kilisesi; bugün sergi salonu olarak kullanılıyor.', null),
  ('ayios-haralambos-kilisesi', 'en', 'Saint Charalambos Church', 'A 19th-century Greek Orthodox church in Çeşme, now used as an exhibition hall.', null),
  ('bet-israel-sinagogu', 'tr', 'Bet İsrael Sinagogu', 'Karataş''ta 20. yüzyılın başında yapılan, İzmir''in bugün de kullanılan büyük sinagoglarından.', null),
  ('bet-israel-sinagogu', 'en', 'Bet Israel Synagogue', 'An early 20th-century synagogue in Karataş, one of Izmir''s large synagogues still in use.', null),
  ('sinyora-giveret-sinagogu', 'tr', 'Sinyora Giveret Sinagogu', 'Kemeraltı''ndaki Havra Sokağı''nın tarihi sinagoglarından; adını bağışçı bir kadından alır.', null),
  ('sinyora-giveret-sinagogu', 'en', 'Signora Giveret Synagogue', 'One of the historic synagogues on Havra Street in Kemeraltı, named after a woman benefactor.', null),
  ('etz-hayim-sinagogu', 'tr', 'Etz Hayim Sinagogu', 'Havra Sokağı''nda, İzmir''in en eski sinagoglarından biri; ''Hayat Ağacı'' anlamına gelir.', null),
  ('etz-hayim-sinagogu', 'en', 'Etz Hayim Synagogue', 'One of Izmir''s oldest synagogues on Havra Street; its name means ''Tree of Life''.', null),
  ('algazi-sinagogu', 'tr', 'Algazi Sinagogu', 'Havra Sokağı''nda 18. yüzyıldan kalan, restore edilmiş sinagog.', null),
  ('algazi-sinagogu', 'en', 'Algazi Synagogue', 'A restored 18th-century synagogue on Havra Street.', null),
  ('latife-hanim-kosku-ani-evi', 'tr', 'Latife Hanım Köşkü Anı Evi', 'Karşıyaka''da, Latife Hanım''ın ailesinin yazlık köşkü; Zübeyde Hanım son günlerini burada geçirdi. Bugün anı evi.', null),
  ('latife-hanim-kosku-ani-evi', 'en', 'Latife Hanım Memorial House', 'The summer mansion of Latife Hanım''s family in Karşıyaka, where Atatürk''s mother spent her last days; now a memorial house.', null),
  ('forbes-kosku', 'tr', 'Forbes Köşkü', 'Buca''da, Levanten Forbes ailesinin 1908''de yaptırdığı ve 1910''da yangından sonra yeniden inşa edilen köşk.', null),
  ('forbes-kosku', 'en', 'Forbes Mansion', 'A mansion in Buca built in 1908 for the Levantine Forbes family and rebuilt after a fire in 1910.', null),
  ('bizans-sarayi', 'tr', 'Bizans Sarayı', 'Efes''te, geç dönem Bizans yöneticilerine ait olduğu düşünülen büyük konut kalıntısı.', null),
  ('bizans-sarayi', 'en', 'Byzantine Palace', 'Remains of a large residence in Ephesus, thought to have housed late Byzantine officials.', null),
  ('v-sarayi', 'tr', 'V Sarayı', 'Pergamon akropolünde, Bergama krallarına ait saraylardan birinin kalıntısı.', null),
  ('v-sarayi', 'en', 'Palace V', 'Ruins of one of the royal palaces of the Pergamene kings on the acropolis.', null),
  ('efes-muzesi', 'tr', 'Efes Müzesi', 'Selçuk''ta, Efes kazılarından çıkan heykel ve eserlerin sergilendiği müze; Artemis heykelleri en ünlüleri.', null),
  ('efes-muzesi', 'en', 'Ephesus Archaeological Museum', 'The museum in Selçuk displaying finds from the Ephesus excavations, best known for its statues of Artemis.', null),
  ('izmir-arkeoloji-muzesi', 'tr', 'İzmir Arkeoloji Müzesi', 'Bahribaba''da, İzmir ve çevresindeki antik kentlerden çıkan heykel, lahit ve sikkeleri sergileyen müze.', null),
  ('izmir-arkeoloji-muzesi', 'en', 'İzmir Archaeological Museum', 'A museum in Bahribaba showing statues, sarcophagi and coins from ancient cities around Izmir.', null),
  ('izmir-kultur-sanat-fabrikasi', 'tr', 'İzmir Kültür Sanat Fabrikası', 'Alsancak''ta, eski tütün fabrikasında açılan; arkeoloji, etnografya ve resim-heykel müzelerini bir araya getiren kültür merkezi.', null),
  ('izmir-kultur-sanat-fabrikasi', 'en', 'İzmir Culture and Art Factory', 'A cultural complex in a former tobacco factory in Alsancak, bringing together archaeology, ethnography and fine arts museums.', null),
  ('izmir-agorasi', 'tr', 'İzmir Agorası', 'Antik Smyrna''nın agorası; Roma dönemi sütunları ve tonozlu bodrum katı açık hava müzesi olarak gezilebiliyor.', null),
  ('izmir-agorasi', 'en', 'Agora of Smyrna', 'The agora of ancient Smyrna; its Roman colonnades and vaulted basements can be visited as an open-air museum.', null),
  ('tcg-pirireis-s-343', 'tr', 'TCG Pirireis (S-343)', 'İnciraltı''nda, 1940''larda yapılıp Türk Deniz Kuvvetleri''nde hizmet veren ve müze gemisi olan denizaltı.', null),
  ('tcg-pirireis-s-343', 'en', 'TCG Pirireis Museum Submarine', 'A 1940s submarine that served in the Turkish Navy, now a museum ship at İnciraltı.', null),
  ('izmir-kadin-muzesi', 'tr', 'İzmir Kadın Müzesi', 'Kemeraltı''nda, İzmirli kadınların hayatını ve tarihini anlatan müze.', null),
  ('izmir-kadin-muzesi', 'en', 'İzmir Women''s Museum', 'A museum in Kemeraltı telling the lives and history of Izmir''s women.', null),
  ('bergama-muzesi', 'tr', 'Bergama Müzesi', 'Bergama''da, Pergamon ve çevresinden çıkan eserlerle Zeus Sunağı''nın maketini sergileyen müze.', null),
  ('bergama-muzesi', 'en', 'İzmir Bergama Museum', 'A museum in Bergama with finds from Pergamon and the region, including a model of the Altar of Zeus.', null),
  ('izmir-ataturk-muzesi', 'tr', 'İzmir Atatürk Müzesi', 'Kordon''da, Atatürk''ün İzmir''e her gelişinde kaldığı köşk; bugün müze.', null),
  ('izmir-ataturk-muzesi', 'en', 'Atatürk Museum', 'The mansion on the Kordon where Atatürk stayed on his visits to Izmir; now a museum.', null),
  ('izmir-etnografya-muzesi', 'tr', 'İzmir Etnografya Müzesi', 'Bahribaba''da eski bir hastane binasında, İzmir''in el sanatlarını ve gündelik yaşamını anlatan müze.', null),
  ('izmir-etnografya-muzesi', 'en', 'İzmir Ethnography Museum', 'A museum in a former hospital building in Bahribaba, showing Izmir''s crafts and everyday life.', null),
  ('umran-baradan-oyun-ve-oyuncak-muzesi', 'tr', 'Ümran Baradan Oyun ve Oyuncak Müzesi', 'Konak''ta, eski oyuncakları ve çocuk oyunlarını sergileyen müze.', null),
  ('umran-baradan-oyun-ve-oyuncak-muzesi', 'en', 'İzmir Toy Museum', 'A museum in Konak displaying old toys and children''s games.', null),
  ('arkas-sanat-merkezi', 'tr', 'Arkas Sanat Merkezi', 'Alsancak''ta, eski Fransız Konsolosluğu binasında açılan sanat müzesi.', null),
  ('arkas-sanat-merkezi', 'en', 'Arkas Art Center', 'An art museum in Alsancak housed in the former French Consulate building.', null),
  ('bostanli-acik-hava-arkeoloji-muzesi', 'tr', 'Bostanlı Açık Hava Arkeoloji Müzesi', 'Karşıyaka''da, antik Smyrna''nın karşı kıyısındaki yerleşimden çıkan kalıntıların açık hava sergisi.', null),
  ('bostanli-acik-hava-arkeoloji-muzesi', 'en', 'Bostanlı Open-air Archaeological Museum', 'An open-air display in Karşıyaka of remains from a settlement across the bay from ancient Smyrna.', null),
  ('cakiraga-konagi', 'tr', 'Çakırağa Konağı', 'Birgi''de 18. yüzyılda yapılan, duvar resimleriyle ünlü üç katlı konak; bugün müze.', null),
  ('cakiraga-konagi', 'en', 'Çakırağa Mansion', 'An 18th-century three-storey mansion in Birgi, famous for its wall paintings; now a museum.', null),
  ('cesme-muzesi', 'tr', 'Çeşme Müzesi', 'Çeşme Kalesi''nin içinde, bölgenin arkeolojisini ve Çeşme Deniz Savaşı''nı anlatan müze.', null),
  ('cesme-muzesi', 'en', 'Çeşme Museum', 'A museum inside Çeşme Castle covering local archaeology and the Battle of Çeşme.', null),
  ('odemis-muzesi', 'tr', 'Ödemiş Müzesi', 'Ödemiş''te, antik Hypaipa ve çevresinden çıkan eserleri sergileyen müze.', null),
  ('odemis-muzesi', 'en', 'Ödemiş Museum', 'A museum in Ödemiş showing finds from ancient Hypaipa and the surrounding area.', null),
  ('ahmet-piristina-kent-arsivi-ve-muzesi', 'tr', 'Ahmet Piriştina Kent Arşivi ve Müzesi', 'Eski itfaiye binasında, İzmir''in kent tarihini fotoğraf ve belgelerle anlatan arşiv-müze.', null),
  ('ahmet-piristina-kent-arsivi-ve-muzesi', 'en', 'Ahmet Piriştina City Archives and Museum', 'An archive and museum in the old fire station, telling Izmir''s city history through photos and documents.', null),
  ('key-museum', 'tr', 'Key Museum', 'Torbalı''da klasik otomobil, motosiklet ve uçakların sergilendiği büyük ulaşım müzesi.', null),
  ('key-museum', 'en', 'Key Museum', 'A large transport museum in Torbalı with classic cars, motorcycles and aircraft.', null),
  ('kadifekale', 'tr', 'Kadifekale', 'Pagos Tepesi''nde, kökeni Büyük İskender dönemine uzanan kale; körfezin en geniş manzarası buradan.', null),
