  ('candarli-kalesi', 'en', 'Çandarlı Castle', 'A well-preserved medieval castle on the shore at Çandarlı.', null),
  ('sigacik-kalesi', 'tr', 'Sığacık Kalesi', 'Seferihisar''da, içinde yaşanan bir köyü çevreleyen 16. yüzyıl Osmanlı kalesi.', null),
  ('sigacik-kalesi', 'en', 'Sığacık Castle', 'A 16th-century Ottoman fortress in Seferihisar that still encloses a lived-in village.', null),
  ('sancakburnu-kalesi', 'tr', 'Sancakburnu Kalesi', 'İnciraltı''nda, körfez girişini korumak için 17. yüzyılda yapılan Osmanlı kalesi.', null),
  ('sancakburnu-kalesi', 'en', 'Sancakburnu Castle', 'An Ottoman fortress at İnciraltı, built in the 17th century to guard the entrance to the bay.', null),
  ('ayasuluk-kalesi', 'tr', 'Ayasuluk Kalesi', 'Selçuk''ta Ayasuluk Tepesi''ni taçlandıran Bizans ve Beylikler dönemi kalesi.', null),
  ('ayasuluk-kalesi', 'en', 'The Grand Fortress of Selçuk', 'The Byzantine and Beylik-era castle crowning Ayasuluk Hill in Selçuk.', null),
  ('izmir-saat-kulesi', 'tr', 'İzmir Saat Kulesi', 'Konak Meydanı''ndaki, 1901''de yapılan ve İzmir''in simgesi olan saat kulesi.', null),
