  ('kemeralti-carsisi', 'tr', 'Kemeraltı Çarşısı', 'Konak''tan Basmane''ye uzanan, han, cami ve sinagoglarıyla İzmir''in yüzyıllık tarihi çarşısı.', null),
  ('kemeralti-carsisi', 'en', 'Kemeraltı Bazaar', 'Izmir''s centuries-old bazaar stretching from Konak to Basmane, full of inns, mosques and synagogues.', null),
  ('memmius-yapisi', 'tr', 'Memmius Yapısı', 'Efes''te, Sulla''nın torunu Memmius adına yapılan anıtın kalıntısı.', null),
  ('memmius-yapisi', 'en', 'Memmius Monument', 'Remains of the monument in Ephesus dedicated to Memmius, grandson of the dictator Sulla.', null),
  ('artemis-tapinagi', 'tr', 'Artemis Tapınağı', 'Dünyanın yedi harikasından biri sayılan Artemis Tapınağı''nın yerinde bugün tek bir sütun yükseliyor.', null),
  ('artemis-tapinagi', 'en', 'Temple of Artemis (Artemision)', 'Site of the Temple of Artemis, one of the Seven Wonders of the Ancient World, where a single column still stands.', null),
  ('efes', 'tr', 'Efes', 'Antik dünyanın en büyük kentlerinden Efes; mermer caddeleri, tiyatrosu ve kütüphanesiyle Türkiye''nin en ünlü ören yeri.', null),
  ('efes', 'en', 'Ephesus', 'Ephesus, one of the great cities of the ancient world; with its marble streets, theatre and library, Turkey''s most famous ruins.', null),
  ('pergamon', 'tr', 'Pergamon', 'Bergama''nın üzerinde, Helenistik krallığın başkenti Pergamon''un akropolü; dik tiyatrosu ve tapınaklarıyla.', null),
  ('pergamon', 'en', 'Pergamon Acropolis', 'The acropolis of Pergamon above Bergama, capital of a Hellenistic kingdom, with its steep theatre and temples.', null),
  ('celsus-kutuphanesi', 'tr', 'Celsus Kütüphanesi', 'Efes''in simgesi; 2. yüzyılda yapılan iki katlı cephesiyle antik dünyanın en ünlü kütüphanelerinden.', null),
  ('celsus-kutuphanesi', 'en', 'Library of Celsus', 'The emblem of Ephesus; its two-storey 2nd-century façade belongs to one of the ancient world''s most famous libraries.', null),
  ('bergama-zeus-sunagi', 'tr', 'Bergama Zeus Sunağı', 'Akropolde Zeus Sunağı''nın temeli; sunağın kendisi bugün Berlin''deki Bergama Müzesi''nde.', null),
  ('bergama-zeus-sunagi', 'en', 'The Great Altar (Pergamon Altar)', 'The foundations of the Altar of Zeus on the acropolis; the altar itself is now in Berlin''s Pergamon Museum.', null),
  ('klazomenai', 'tr', 'Klazomenai', 'Urla''da, İyon kentlerinden Klazomenai''nin kalıntıları; antik zeytinyağı işliğiyle bilinir.', null),
  ('klazomenai', 'en', 'Klazomenai', 'Remains of the Ionian city of Klazomenai in Urla, known for its ancient olive-oil workshop.', null),
  ('kolophon', 'tr', 'Kolophon', 'Değirmendere yakınında, süvarileriyle ünlü İyon kenti Kolophon''un kalıntıları.', null),
  ('kolophon', 'en', 'Colophon', 'Remains of the Ionian city of Colophon near Değirmendere, famed in antiquity for its cavalry.', null),
  ('smyrna', 'tr', 'Smyrna', 'Bayraklı''daki Tepekule''de, İzmir''in ilk kuruluş yeri olan Eski Smyrna''nın kalıntıları.', null),
