  ('teos', 'tr', 'Teos', 'Seferihisar''da, Dionysos Tapınağı ve tiyatrosuyla İyon kenti Teos''un kalıntıları.', null),
  ('teos', 'en', 'Teos', 'Remains of the Ionian city of Teos in Seferihisar, with its Temple of Dionysus and theatre.', null),
  ('kyme', 'tr', 'Kyme', 'Aliağa''da, Aiolis bölgesinin en önemli kentlerinden Kyme''nin kalıntıları.', null),
  ('kyme', 'en', 'Cyme', 'Remains of Cyme in Aliağa, one of the leading cities of ancient Aeolis.', null),
  ('klaros', 'tr', 'Klaros', 'Ahmetbeyli''de, antik dünyanın ünlü kehanet merkezi Apollon Klarios Tapınağı''nın kalıntıları.', null),
  ('klaros', 'en', 'Claros', 'Remains of the Temple of Apollo Clarios at Ahmetbeyli, a famous oracle of the ancient world.', null),
  ('lebedos', 'tr', 'Lebedos', 'Ürkmez yakınında bir yarımada üzerinde, İyon kenti Lebedos''un kalıntıları.', null),
  ('lebedos', 'en', 'Levedos', 'Remains of the Ionian city of Lebedos on a small peninsula near Ürkmez.', null),
  ('meryem-kilisesi', 'tr', 'Meryem Kilisesi', 'Efes''te, 431''deki Üçüncü Ekümenik Konsil''in toplandığı Meryem Kilisesi''nin kalıntıları.', null),
  ('meryem-kilisesi', 'en', 'Church of Mary', 'Remains of the Church of Mary in Ephesus, where the Third Ecumenical Council met in 431.', null),
  ('notion', 'tr', 'Notion', 'Ahmetbeyli''de denize bakan bir tepede, Kolophon''un limanı Notion''un kalıntıları.', null),
  ('notion', 'en', 'Notion', 'Remains of Notion, the harbour of Colophon, on a hill above the sea at Ahmetbeyli.', null),
  ('kizil-avlu', 'tr', 'Kızıl Avlu', 'Bergama''da, Mısır tanrıları için yapılan dev tuğla tapınak; sonradan kiliseye dönüştürülmüş.', null),
  ('kizil-avlu', 'en', 'Red Basilica', 'A huge brick temple in Bergama built for Egyptian gods and later converted into a church.', null),
  ('larissa', 'tr', 'Larissa', 'Menemen''de, Aiolis kentlerinden Larissa''nın kalıntıları.', null),
