  ('degirmendere-selalesi', 'tr', 'Değirmendere Şelalesi', 'Değirmendere''de, orman içinde kısa yürüyüşle ulaşılan şelale.', 'İlkbahar (su bol)'),
  ('degirmendere-selalesi', 'en', 'Değirmendere Waterfall', 'A waterfall in the woods at Değirmendere, reached by a short walk.', 'Spring (most water)'),
  ('buyuk-su-ucuran-selalesi', 'tr', 'Büyük Su Uçuran Şelalesi', 'Menemen''in dağlarında, yürüyüşle ulaşılan yüksek şelale.', 'İlkbahar (su bol)'),
